    public void setInqtrandTranAmountRounded(BigDecimal value) {
        setDecimal(INQTRAND_TRAN_AMOUNT, value, true);
    }

    /** COBOL class test {@code IF INQTRAND-TRAN-AMOUNT NUMERIC}. */
    public boolean isInqtrandTranAmountNumeric() {
        return isNumericValid(INQTRAND_TRAN_AMOUNT);
    }
